def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""

    resultado = []
    contador = 1

    for i in range(1, len(texto)):
        if texto[i] == texto[i-1]:
            contador += 1
        else:
            resultado.append(texto[i-1] + str(contador))
            contador = 1

    # Agregar el último grupo
    resultado.append(texto[-1] + str(contador))

    return "".join(resultado)

def aplanar(datos: list) -> list:
    resultado = []
    for elemento in datos:
        if isinstance(elemento, (list, tuple)):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def parsear_ventas(texto: str) -> list[dict]:
    import csv

    lines = texto.splitlines()

    # Filtrar líneas vacías o con solo espacios
    non_empty_lines = [line for line in lines if line.strip()]

    if not non_empty_lines:
        return []

    expected_header = "fecha,producto,cantidad,precio"
    if non_empty_lines[0] != expected_header:
        raise ValueError("La cabecera no es la indicada")

    result = []

    for line in non_empty_lines[1:]:
        # Usar csv reader para manejar correctamente campos con comas dentro de comillas
        row = next(csv.reader([line]))

        if len(row) != 4:
            raise ValueError("Una fila no tiene exactamente 4 campos")

        fecha, producto, cantidad_str, precio_str = row

        # Validar cantidad: debe ser entero y no negativa
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("cantidad no es un entero")

        if cantidad < 0:
            raise ValueError("cantidad no puede ser negativa")

        # Validar precio: debe ser un número (float)
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("precio no es un número")

        result.append({
            "fecha": fecha,
            "producto": producto,
            "cantidad": cantidad,
            "precio": precio
        })

    return result

from datetime import datetime

def parsear_fecha(texto: str) -> str:
    # Eliminar espacios al principio y al final
    texto = texto.strip()

    if not texto:
        raise ValueError("Fecha no válida")

    # Formato 1: AAAA-MM-DD (dos partes)
    try:
        dt = datetime.strptime(texto, "%Y-%m-%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Formato 2: DD/MM/AAAA (dos partes)
    try:
        dt = datetime.strptime(texto, "%d/%m/%Y")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Formato 3: D de MES de AAAA (cinco partes: día, "de", mes, "de", año)
    month_map = {
        "enero": 1, "febrero": 2, "marzo": 3, "abril": 4,
        "mayo": 5, "junio": 6, "julio": 7, "agosto": 8,
        "septiembre": 9, "octubre": 10, "noviembre": 11, "diciembre": 12
    }

    try:
        parts = texto.split()
        if len(parts) != 5:
            raise ValueError("Formato incorrecto")

        dia_str, de1, mes_str, de2, año_str = parts

        # Validar que el día sea numérico
        if not dia_str.isdigit():
            raise ValueError("Día no válido")

        # Validar que el mes esté en la tabla
        if mes_str not in month_map:
            raise ValueError("Mes no válido")

        dia = int(dia_str)
        mes = month_map[mes_str]
        año = int(año_str)

        dt = datetime(year=año, month=mes, day=dia)
        return dt.strftime("%Y-%m-%d")
    except (ValueError, KeyError):
        pass

    # Si ninguna de las formas coincide
    raise ValueError("Fecha no válida")

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Mover al final para marcar como usado recientemente
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if self.capacidad == 0:
            return

        if clave in self._datos:
            # La clave ya existe: actualizar valor y marcar como usado
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            # Nueva clave: si está llena, descartar la menos usada (primero)
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
